CREATE TABLE "WebsiteMedia" (
  id TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE ON UPDATE CASCADE,
  page TEXT NOT NULL, language TEXT NOT NULL, section INTEGER NOT NULL, kind TEXT NOT NULL,
  label TEXT NOT NULL, url TEXT, file BYTEA, mime TEXT, version INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX "WebsiteMedia_tenantId_page_language_idx" ON "WebsiteMedia"("tenantId",page,language);
INSERT INTO "WebsiteMedia" (id,"tenantId",page,language,section,kind,url,label)
SELECT md5(t.id || '/' || v.page || '/' || v.language || '/' || v.section || '/' || v.url),t.id,v.* FROM "Tenant" t CROSS JOIN (VALUES
